import 'jest';
import { CURRENCY_DEFAULTS, formatCurrency, unformatCurrency } from '../../src';

describe('formatCurrency()', () => {
    test('should format to GBP correctly', () => {
        expect(formatCurrency(12345, {...CURRENCY_DEFAULTS.GBP})).toEqual('£123.45');
    });
    test('should round on whole units if the option is specified', () => {
        expect(formatCurrency(12300, {...CURRENCY_DEFAULTS.GBP, roundOnWholeUnits: true})).toEqual('£123');
    });
    test('should not trim non-zero subunits even if roundOnWholeUnits is true', () => {
        expect(formatCurrency(12345, {...CURRENCY_DEFAULTS.GBP, roundOnWholeUnits: true})).toEqual('£123.45');
    });
    test('should format to EUR correctly', () => {
        expect(formatCurrency(12345, {...CURRENCY_DEFAULTS.EUR})).toEqual('123,45€');
    });
    test('should format to DKK correctly', () => {
        expect(formatCurrency(12345, {...CURRENCY_DEFAULTS.DKK})).toEqual('123,45 kr.');
    });
    test('should format to SEK correctly', () => {
        expect(formatCurrency(12345, {...CURRENCY_DEFAULTS.SEK})).toEqual('123,45 kr');
    });
    test('should format to NLEUR correctly', () => {
        expect(formatCurrency(12345, {...CURRENCY_DEFAULTS.NLEUR})).toEqual('€123,45');
    });
    test('should return only the subunits if the option is specified and the subunits are low enough', () => {
        expect(formatCurrency(45, {...CURRENCY_DEFAULTS.GBP}, true)).toEqual('45p');
    });
    test('should return units and subunits if the subunits are higher than the threshold', () => {
        expect(formatCurrency(145, {...CURRENCY_DEFAULTS.GBP}, true)).toEqual('£1.45');
    });
    test('should throw an error if returnSubUnits is true but there are no subunit settings', () => {
        expect(() => formatCurrency(45, {symbol: '£',format: '%s%v',decimal: '.',thousand: ',',precision: 2,unitDivider: 100,}, true)).toThrow();
    });
});

describe('unformatCurrency()', () => {
    test('should return the raw subunits', () => {
        expect(unformatCurrency('£123.45', {...CURRENCY_DEFAULTS.GBP})).toEqual(12345);
    });
    test('should return the decimal value if returnBalanceAsPence is false', () => {
        expect(unformatCurrency('£123.45', {...CURRENCY_DEFAULTS.GBP}, false)).toEqual(123.45);
    });
    test('should return the input as a number if returnBalanceAsPence is false and input is not formatted', () => {
        expect(unformatCurrency('45', {...CURRENCY_DEFAULTS.GBP}, false)).toEqual(45);
    });
});